"""Hamilton STAR water liquid classes for CO-RE tips on the independent channels.

Values are Hamilton's default ``*_Water_*`` classes as tabulated in PyLabRobot (MIT), restated
as data. A class is chosen by (nominal tip volume, filter, jet, empty): jet dispenses from
above the liquid, surface dispenses touch it; "empty" classes add blow-out air so the tip can be
emptied completely. The firmware has no liquid classes of its own: every value is sent with
each command. Volumes are corrected along the piecewise-linear ``curve``.
"""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class LiquidClass:
    curve: tuple[tuple[float, float], ...]
    """(target µL, µL to move) points; between them the correction is linear."""
    aspirate_flow: float
    aspirate_transport_air: float
    aspirate_blow_out: float
    aspirate_swap_speed: float
    aspirate_settling_s: float
    clot_retract_mm: float
    dispense_flow: float
    dispense_transport_air: float
    dispense_blow_out: float
    dispense_swap_speed: float
    dispense_settling_s: float
    stop_back_ul: float

    def corrected(self, volume_ul: float) -> float:
        points = self.curve
        if volume_ul <= points[0][0]:
            return volume_ul
        for (x0, y0), (x1, y1) in zip(points, points[1:]):
            if volume_ul <= x1:
                return y0 + (y1 - y0) * (volume_ul - x0) / (x1 - x0)
        (x0, y0), (x1, y1) = points[-2], points[-1]
        return y1 + (y1 - y0) / (x1 - x0) * (volume_ul - x1)


def _lc(curve: tuple[tuple[float, float], ...], *values: float) -> LiquidClass:
    return LiquidClass(curve, *values)


