def water_class(tip_volume_ul: float, has_filter: bool, jet: bool, empty: bool, *, core96: bool = False) -> LiquidClass | None:
    """The closest water class: exact match, else flip ``empty``, else flip ``jet``, else both."""
    table = CORE96_WATER if core96 else WATER
    tip = int(round(tip_volume_ul))
    for j, e in ((jet, empty), (jet, not empty), (not jet, empty), (not jet, not empty)):
        lc = table.get((tip, has_filter, j, e))
        if lc is not None:
            return lc
    return None
